#!/usr/bin/env node
// Compare two directories of reference JSON files (committed vs regenerated by Octave).
// Usage: node tools/compare-refs.mjs <committed-dir> <regenerated-dir>
// Numbers match when |a - b| <= 1e-12 + 1e-9 * max(|a|, |b|): BLAS round-off
// differs between machines; anything larger means a script changed without
// its references being regenerated. Exit code 1 on any difference.
import { readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';

const [dirA, dirB] = process.argv.slice(2);
if (!dirA || !dirB) {
  console.error('usage: node tools/compare-refs.mjs <committed-dir> <regenerated-dir>');
  process.exit(2);
}

const REL = 1e-9;
const ABS = 1e-12;
const diffs = [];

function same(a, b, path) {
  if (diffs.length > 50) return;
  if (typeof a === 'number' && typeof b === 'number') {
    if (Math.abs(a - b) > ABS + REL * Math.max(Math.abs(a), Math.abs(b))) diffs.push(`${path}: ${a} vs ${b}`);
    return;
  }
  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) return void diffs.push(`${path}: length ${a.length} vs ${b.length}`);
    a.forEach((v, i) => same(v, b[i], `${path}[${i}]`));
    return;
  }
  if (a && b && typeof a === 'object' && typeof b === 'object' && !Array.isArray(a) && !Array.isArray(b)) {
    const ka = Object.keys(a).sort();
    const kb = Object.keys(b).sort();
    const missing = ka.filter((k) => !(k in b));
    const extra = kb.filter((k) => !(k in a));
    if (missing.length) diffs.push(`${path}: missing in regenerated: ${missing.join(', ')}`);
    if (extra.length) diffs.push(`${path}: new in regenerated: ${extra.join(', ')}`);
    for (const k of ka) if (k in b) same(a[k], b[k], `${path}.${k}`);
    return;
  }
  if (a !== b) diffs.push(`${path}: ${JSON.stringify(a)} vs ${JSON.stringify(b)}`);
}

const files = (d) => readdirSync(d).filter((f) => f.endsWith('.json')).sort();
const fa = files(dirA);
const fb = files(dirB);
for (const f of fa.filter((f) => !fb.includes(f))) diffs.push(`${f}: not regenerated`);
for (const f of fb.filter((f) => !fa.includes(f))) diffs.push(`${f}: not committed`);
for (const f of fa.filter((f) => fb.includes(f))) {
  const a = JSON.parse(readFileSync(join(dirA, f), 'utf8'));
  const b = JSON.parse(readFileSync(join(dirB, f), 'utf8'));
  delete a.generator; // tool versions are informative only
  delete b.generator;
  same(a, b, f);
}

if (diffs.length) {
  console.error(`${diffs.length} difference(s) between ${dirA} and ${dirB}:`);
  for (const d of diffs.slice(0, 50)) console.error('  ' + d);
  console.error('\nRegenerate with: octave-cli --eval "addpath(\'matlab/refs\'); export_refs"');
  process.exit(1);
}
console.log(`OK: ${fa.length} reference files match (rel ${REL}, abs ${ABS}).`);
